document.addEventListener('DOMContentLoaded', () => {
    const name = document.querySelector('.hero-name'); const socialLinks = document.querySelectorAll('.social-links a'); if (name && socialLinks.length) { const original = name.textContent; let swapTimeout; const swapTo = (text) => { clearTimeout(swapTimeout); name.classList.add('is-swapping'); swapTimeout = setTimeout(() => { name.textContent = text; name.classList.remove('is-swapping') }, 180) }; socialLinks.forEach(link => { link.addEventListener('mouseenter', () => swapTo(link.dataset.name || original)); link.addEventListener('mouseleave', () => swapTo(original)) }) }
    updateBuildInfo()
}); const BUILD_KEY = 'build-info'; const BUILD_TTL = 10 * 60 * 1000; function readCache() { try { return JSON.parse(localStorage.getItem(BUILD_KEY)) } catch { return null } }
function writeCache(data) { try { localStorage.setItem(BUILD_KEY, JSON.stringify(data)) } catch { } }
function renderBuildInfo({ sha, date } = {}) { const localDate = date ? new Date(date).toLocaleString('en-US', { month: 'short', year: 'numeric', day: 'numeric', }) : null; const commitEl = document.getElementById('last-commit'); const updateEl = document.getElementById('last-update'); if (commitEl) commitEl.textContent = sha || 'N/A'; if (updateEl) updateEl.textContent = localDate || 'N/A' }
async function updateBuildInfo() {
    const cached = readCache(); if (cached && Date.now() < cached.next) { renderBuildInfo(cached); return }
    try { const res = await fetch('https://api.github.com/repos/infinotiver/infinotiver.github.io/commits?per_page=1'); if (!res.ok) throw new Error(`GitHub API ${res.status}`); const [commit] = await res.json(); const data = { sha: commit?.sha.substring(0, 7), date: commit?.commit.author.date, next: Date.now() + BUILD_TTL, }; writeCache(data); renderBuildInfo(data) } catch (err) { console.error('Error fetching GitHub data:', err); if (cached) { writeCache({ ...cached, next: Date.now() + BUILD_TTL }); renderBuildInfo(cached) } else { renderBuildInfo() } }
}